    // Checks that a reused font cell repaints its whole area after paging.
    // Qt 5.2 does not repaint a hidden caption's area; desktop Qt 6 does, so this cannot show that failure.
    void fontPagingClearsCaptions()
    {
        // Font pages reuse their cells. A cell that shows another font must
        // repaint completely, so a caption from the previous page cannot stay
        // on screen. Qt 5.2 on Kobo leaves a hidden caption's area unpainted
        // unless the cell asks for a full repaint. Desktop Qt 6 repaints that
        // area by itself, so this check guards the contract but cannot show
        // the Qt 5.2 failure.
        Fixture fixture;
        QVERIFY(fixture.prepared);
        QSignalSpy opened(&fixture.window, &desktop::Window::bookOpened);
        fixture.window.openBook(book);
        QTRY_COMPARE(opened.count(), 1);
        QTRY_VERIFY(!fixture.state().value("busy").toBool());
        QVERIFY(fixture.press("readingPage"));
        QVERIFY(fixture.press("navigationText"));
        QVERIFY(fixture.press("appearanceFont"));
        QTRY_VERIFY(fixture.visible("choices"));
        auto *choices = dynamic_cast<ChoiceScreen *>(fixture.widget("choices"));
        QVERIFY(choices);
        QVector<Choice> fonts{
            { "Publisher Fonts", {}, "testFont0", "Fonts", 0, -1, "No embedded fonts\nUses Libron" }
        };
        for (int i = 1; i < 40; ++i)
            fonts.append(
                    { QString("Font %1").arg(i), "Libron", QString("testFont%1").arg(i), "Fonts" });
        choices->showChoices("Font", fonts, {}, ChoiceScreen::Mode::Fonts);
        QTRY_VERIFY(fixture.visible("testFont0Detail"));
        auto *cell = fixture.widget("testFont0");
        QVERIFY(cell);
        QTest::qWait(100);

        struct Paints : QObject
        {
            QRegion painted;

            bool eventFilter(QObject *, QEvent *event) override
            {
                if (event->type() == QEvent::Paint)
                    painted += static_cast<QPaintEvent *>(event)->region();
                return false;
            }
        } paints;

        cell->installEventFilter(&paints);
        QVERIFY(fixture.press("fontPagerNext"));
        QTRY_VERIFY(cell->isVisible() && cell->objectName() != "testFont0");
        QTRY_VERIFY2(paints.painted.contains(cell->rect()),
                     "A reused font cell kept pixels from the previous page");
        cell->removeEventFilter(&paints);
    }

    // Checks bundled families, both sides of the interface font limit and retention after selection.
    void interfaceFontSizeLimit()
    {
        QTemporaryDir fonts;
        QVERIFY(fonts.isValid());
        const auto source = assets->file("fonts/ebook-core/NV_Bitter-Regular.ttf");
        const auto small = fonts.filePath("KF_Small.ttf"), large = fonts.filePath("KF_Large.ttf");
        QVERIFY(test::renamedFontFixture(source, small, "NV Bitter", "KF Little"));
        QVERIFY(test::renamedFontFixture(source, large, "NV Bitter", "KF Bigger"));
        // Padding after the tables leaves the font valid.
        QVERIFY(QFile::resize(small, interfaceFontByteLimit - 1));
        QVERIFY(QFile::resize(large, interfaceFontByteLimit));
        Fixture fixture(false, false, false, true, false, false, {}, fonts.path());
        QVERIFY(fixture.prepared);
        QSignalSpy opened(&fixture.window, &desktop::Window::bookOpened);
        fixture.window.openBook(book);
        QTRY_COMPARE(opened.count(), 1);
        QTRY_VERIFY(!fixture.state().value("busy").toBool());
        QVERIFY(fixture.press("readingPage"));
        QVERIFY(fixture.press("readingMenuSettings"));
        QVERIFY(fixture.press("settingsSystem"));
        QVERIFY(revealSettingsOption(fixture, "settingsTheming"));
        QVERIFY(fixture.press("settingsTheming"));
        if (ui::colorThemes) {
            QVERIFY(fixture.press("settingsThemePreset"));
            QVERIFY(fixture.press("settingsTheme_custom"));
        }
        QVERIFY(revealSettingsOption(fixture, "settingsUiFont"));
        QVERIFY(fixture.press("settingsUiFont"));
        QTRY_VERIFY(fixture.visible("settingsFontPopup"));
        auto *list = static_cast<ui::RadioList *>(fixture.widget("settingsFontChoices"));
        QVERIFY(list);
        ui::DescribedOption *smallRow = nullptr, *largeRow = nullptr;
        QStringList enabledFamilies;
        for (auto *option : list->options()) {
            const auto family = option->property("reader_font_family").toString();
            if (option->isEnabled())
                enabledFamilies.append(family);
            if (family == "KF Little")
                smallRow = option;
            if (family == "KF Bigger")
                largeRow = option;
        }
        QVERIFY(enabledFamilies.contains("NV Garamond"));
        QVERIFY(enabledFamilies.contains("NV Charis"));
        QVERIFY(smallRow && largeRow);
        QVERIFY(smallRow->isEnabled());
        QVERIFY(!largeRow->isEnabled());
        QCOMPARE(largeRow->accessibleDescription(), strings::get("settings.font_too_large"));
        fixture.press(largeRow->objectName().toLatin1().constData());
        QVERIFY2(fixture.visible("settingsFontPopup"), "A disabled font was chosen");
        QVERIFY(fixture.press(smallRow->objectName().toLatin1().constData()));
        QTRY_COMPARE(ui::interfaceFont().family(), QString("KF Little"));
        // The chosen faces stay in memory: interface text draws without the file.
        QVERIFY(QFile::remove(small));
        ui::refreshInterfaceText(fixture.window.readerWindow());
        QVERIFY(!ui::renderPrivateText("Mark text", ui::interfaceFont(20)).image.isNull());
    }

