        QCOMPARE(saved()[1].name, QString("Evening"));
        QCOMPARE(saved()[2].id, QString("kobalt"));
        const auto order = saved();
        QTRY_VERIFY(grid->isEnabled());
        // Save is first, Morning second, Evening third. Applying Evening keeps the order.
